    int rmin = *min_element(ranks.begin(), ranks.end());
    int hi = rmin * n * (n + 1) / 2;
    int lo = 0, ans = hi;

    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (canMake(ranks, n, mid)) {
            ans = mid;
